def add_strings(a, b):
    i, j, carry, out = len(a) - 1, len(b) - 1, 0, []
    while i >= 0 or j >= 0 or carry:
        x = ord(a[i]) - ord('0') if i >= 0 else 0
        y = ord(b[j]) - ord('0') if j >= 0 else 0
        carry, d = divmod(x + y + carry, 10)
        out.append(chr(d + ord('0')))
        i, j = i - 1, j - 1
    return ''.join(reversed(out))

