def next_greater(nums):
    ans = [-1] * len(nums)
    st = []                       # indices; their values are decreasing
    for i, x in enumerate(nums):
        while st and nums[st[-1]] < x:
            ans[st.pop()] = x
        st.append(i)
    return ans
