def count_calls(n):
    calls = 0
    def go(k):
        nonlocal calls           # change the outer variable
        calls += 1
        if k > 0:
            go(k - 1)
    go(n)
    return calls
print(count_calls(5))
print(sys.getrecursionlimit())

