from collections import deque
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def build(level):                  # from LeetCode's list form; None = no node
    if not level:
        return None
    it = iter(level)
    root = TreeNode(next(it))
    q = deque([root])
    while q:
        node = q.popleft()
        for side in ("left", "right"):
            v = next(it, None)
            if v is not None:
                child = TreeNode(v)
                setattr(node, side, child)
                q.append(child)
    return root

def inorder(node):
    return inorder(node.left) + [node.val] + inorder(node.right) if node else []

def depth(node):
    return 1 + max(depth(node.left), depth(node.right)) if node else 0

def level_order(root):
    res, q = [], deque([root] if root else [])
    while q:
        level = []
        for _ in range(len(q)):         # one level at a time
            node = q.popleft()
            level.append(node.val)
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)
        res.append(level)
    return res

root = build([3, 9, 20, None, None, 15, 7])
print(inorder(root), depth(root), level_order(root))

